/**
 * ARGUE IT tables on the framework database (plan Task 1).
 *
 * 1. Applies drizzle/*.sql (generated by `pnpm db:generate` from server/domain/db/schema.ts) through the
 *    framework's migration runner. Bookkeeping lives in `argue_it_migrations` / `argue_it_migrations_named`
 *    (file name = stable migration name), not drizzle-kit's `__drizzle_migrations`.
 * 2. Opens the shared connection so request-time `db` calls get the real Drizzle instance (see @domain/db).
 * 3. Seeds the 5 launch categories and mirrors the code rubrics into `rubrics`, as the reference
 *    `ensureDatabaseReady()` did. Both are idempotent.
 */
import path from "node:path";

import { runDrizzleMigrations } from "@agent-native/core/db/drizzle-migrations";
import { ensureDbReady } from "@domain/db";
import { seedCategories } from "@domain/db/categories-seed";
import { syncRubrics } from "@domain/judging/rubrics";

/** Resolved from the app root: the bundled server file does not sit next to drizzle/. */
export const MIGRATIONS_FOLDER = path.join(process.cwd(), "drizzle");
export const MIGRATIONS_TABLE = "argue_it_migrations";

const migrate = runDrizzleMigrations(MIGRATIONS_FOLDER, { table: MIGRATIONS_TABLE });

export default async function argueItDbPlugin(nitroApp: unknown): Promise<void> {
  await migrate(nitroApp);
  try {
    const db = await ensureDbReady();
    await seedCategories(db);
    await syncRubrics(db);
  } catch (error) {
    // Never take the server down over reference data; the next boot retries.
    console.error("[argue-it db] seeding categories/rubrics failed:", error instanceof Error ? error.message : error);
  }
}
